module parity_8bit (
    input [7:0] in,
    output out
);
    assign out = ^in;
endmodule

module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    assign out = (sel == 2'd0) ? in[0] : (sel == 2'd1) ? in[1] : (sel == 2'd2) ? in[2] : in[3];
endmodule

module majority (
    input a, b, c,
    output out
);
assign out = (a & b) | (b & c) | (a & c);
endmodule

module bin_to_gray (
    input [3:0] binary,
    output [3:0] gray
);
    assign gray[3] = binary[3];
    assign gray[2] = binary[3] ^ binary[2];
    assign gray[1] = binary[2] ^ binary[1];
    assign gray[0] = binary[1] ^ binary[0];
endmodule

module eq_comparator (
    input [3:0] a,
    input [3:0] b,
    output equal
);
    assign equal = (a == b);
endmodule

module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);
    assign out = {1'b0, 1'b0, in, ~in};
endmodule

module priority_encoder (
    input [3:0] in,
    output reg [1:0] code
);
always @(*) begin
    case (in)
        4'b0001: code = 2'b00;
        4'b0011: code = 2'b01;
        4'b0111: code = 2'b10;
        4'b1111: code = 2'b11;
        default: code = 2'b00;
    endcase
end
endmodule

module fsm_3state (
    input clk, reset,
    output [1:0] state
);
    reg [1:0] state;
    always @ (posedge clk or negedge reset) begin
        if (!reset) begin
            state <= 2'b00;
        end
        else begin
            case (state)
                2'b00: state <= 2'b01;
                2'b01: state <= 2'b10;
                2'b10: state <= 2'b00;
            endcase
        end
    end
endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);
    reg [2:0] light;
    reg [2:0] current_state;
    reg [2:0] next_state;
    reg [3:0] count;

    always @ (posedge clk or negedge reset) begin
        if (!reset) begin
            current_state <= 3'd0;
            count <= 4'd0;
        end
        else begin
            current_state <= next_state;
            if (count < 4'd4) begin
                count <= count + 4'd1;
            end
            else begin
                count <= 4'd0;
                next_state <= (current_state == 3'd0) ? 3'd1 : (current_state == 3'd1) ? 3'd2 : 3'd0;
            end
        end
    end

    always @ (current_state) begin
        case (current_state)
            3'd0: light = 3'b001;
            3'd1: light = 3'b010;
            3'd2: light = 3'b100;
            default: light = 3'b001;
        endcase
    end
endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);
    reg [1:0] next_state, current_state;
    reg [1:0] state_reg;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= 2'b00;
        end else begin
            state_reg <= next_state;
        end
    end

    always @(*) begin
        next_state = current_state;
        case (current_state)
            2'b00: begin
                if (up_request) next_state = 2'b01;
                else if (down_request) next_state = 2'b10;
            end
            2'b01: begin
                if (down_request) next_state = 2'b10;
            end
            2'b10: begin
                if (up_request) next_state = 2'b01;
            end
        endcase
    end

    assign state = current_state;
endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);
    reg [1:0] state, next_state;
    wire [1:0] level_0, level_1;

    assign state = state;

    // State transitions and state register
    always @ (posedge clk or posedge reset) begin
        if (reset) begin
            state <= 0;
        end else begin
            state <= next_state;
        end
    end

    // State machine logic
    always @* begin
        level_0 = {2'd0, 2'd0};
        level_1 = {2'd0, 2'd1};
        next_state = level_0;
        if (state == level_1) begin
            if (coin_inserted) begin
                next_state = level_1;
            end else if (item_selected) begin
                next_state = level_0;
            end else begin
                next_state = state;
            end
        end
        if (state == level_0) begin
            if (coin_inserted) begin
                next_state = level_1;
            end else begin
                next_state = state;
            end
        end
    end
endmodule

module power (
    input signed [7:0] in_0,
    input signed [3:0] in_1,
    output signed [15:0] out
);
    assign out = {{8{in_1[3]}}, in_0} * in_1;
endmodule

module log2_int (
    input signed [15:0] in_0,
    output signed [7:0] out
);
    always @(*) begin
        if (in_0 == 0) out = -1'd1;  else out = $clog2(in_0);
    end
endmodule

module add_8bit (
    input signed [7:0] a, b,
    output signed [8:0] out
);
    assign out = a + b;
endmodule

module mult_4bit (
    input [3:0] a, b,
    output [7:0] out
);
    wire [7:0] product;
    assign product = a * b;
    assign out = product;
endmodule

module subtract_8bit (
    input signed [7:0] a, b,
    output signed [8:0] diff
);
    assign diff = a - b;
endmodule

module bitwise_ops (
    input [7:0] a, b,
    output [7:0] and_out,
    output [7:0] or_out,
    output [7:0] xor_out
);
    assign and_out = a & b;
    assign or_out = a | b;
    assign xor_out = a ^ b;
endmodule

module left_shift (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    assign out = {in[6:0] >> shift, 1'b0};
endmodule

module bitwise_not (
    input [7:0] in,
    output [7:0] out
);
    assign out = ~in;
endmodule

module rotate_left (
    input [7:0] in,
    input [2:0] shift,
    output [7:0] out
);
    assign out = {in[7 - shift: 0] , in[7 - shift + 1 : 7]};
endmodule

module relu (
    input signed [15:0] in_0,
    output signed [15:0] out);
    assign out = (in_0 < 16'd0) ? 16'd0 : in_0;
endmodule

module caesar_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);

    assign data_out = data_in + 3'd5;

endmodule

module modular_add_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    assign data_out = data_in + 46;
endmodule

module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 8'hA5; // Example key

    wire [7:0] left, right, f_out;

    assign left = data_in[7:4];
    assign right = data_in[3:0];

    assign f_out = right ^ KEY;

    assign data_out = {right, f_out};
endmodule

module clock_div2 (
    input clk,
    input rst,
    output clk_out
);
    reg [15:0] counter;
    always @ (posedge clk or posedge rst) begin
        if (rst) begin
            counter <= 16'd0;
            clk_out <= 1'b0;
        end
        else begin
            if (counter == 16'd16383) begin
                counter <= 16'd0;
                clk_out <= ~clk_out;
            end
            else begin
                counter <= counter + 1'b1;
            end
        end
    end
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    assign gt = (a > b);
    assign lt = (a < b);
    assign eq = (a == b);
endmodule

module decoder_2to4 (
    input  [1:0] in,
    input        enable,
    output [3:0] out
);
    assign out[0] = enable & (~in[0]) & (~in[1]);
    assign out[1] = enable & (~in[0]) & (in[1]);
    assign out[2] = enable & (in[0]) & (~in[1]);
    assign out[3] = enable & (in[0]) & (in[1]);
endmodule

module decoder3to8(input [2:0] in, input enable, output [7:0] out);
    assign out = enable ? (1 << in) : 8'h00;
endmodule

module demux_1to2 (
    input  in,
    input  sel,
    output out0,
    output out1
);
    assign out0 = ~sel & in;
    assign out1 = sel & in;
endmodule

module demux_1to4 (
    input        in,
    input  [1:0] sel,
    output       out0,
    output       out1,
    output       out2,
    output       out3
);
    assign out0 = (sel == 2'b00) ? in : 1'bz;
    assign out1 = (sel == 2'b01) ? in : 1'bz;
    assign out2 = (sel == 2'b10) ? in : 1'bz;
    assign out3 = (sel == 2'b11) ? in : 1'bz;
endmodule

module gray_counter8(
    input wire clk,
    input wire rst,
    output wire [7:0] count
);
reg [7:0] reg_count;

always @ (posedge clk) begin
    if (rst) begin
        reg_count <= 8'h00;
    end
    else if (count != 8'h00) begin
        reg_count <= reg_count ^ 8'h11;
    end
end

assign count = reg_count;
endmodule

module johnson_counter4 (
    input clk,
    input rst,
    output [3:0] q
);
reg [3:0] q_register;
always @(posedge clk or posedge rst) begin
    if (rst) begin
        q_register <= 4'b0000;
    end
    else begin
        q_register <= {q_register[2:0], ~q_register[0]};
    end
end
assign q = q_register;
endmodule

module piso_8bit(
    input clk,
    input rst,
    input load,
    input [7:0] pin,
    output sout
);
    reg [7:0] reg_8;
    wire [7:0] reg_8_out;
    // Logic for register
    always @(posedge clk) begin
        if (rst) begin
            reg_8 <= 8'b0;
        end
        else if (load) begin
            reg_8 <= pin;
        end
        else begin
            reg_8 <= {reg_8[6:0], 1'b0};
        end
    end
    assign sout = reg_8[7];
endmodule

