module ring_counter4 (
    input clk,
    input rst,
    output [3:0] q
);

reg [3:0] q_reg;

always @(posedge clk or posedge rst) begin
    if (rst) begin
        q_reg <= 4'b0001;
    end else begin
        q_reg <= {q_reg[2:0], 1'b0};
    end
end

assign q = q_reg;

endmodule

module sipo_8bit(
    input clk,
    input rst,
    input sin,
    output [7:0] pout
);
    reg [7:0] r;

    always @(posedge clk) begin
        if (rst) begin
            r <= 8'd0;
        end
        else begin
            r <= {r[6:0], sin};
        end
    end

    assign pout = r;
endmodule

module siso_8bit(
    input clk,
    input rst,
    input sin,
    output sout
);
    wire [7:0] reg;
    always @(posedge clk or posedge rst) begin
        if (rst) reg <= 8'b0;
        else reg <= {reg[6:0], sin};
    end
    assign sout = reg[7];
endmodule

module up_counter8(
    input clk,
    input rst,
    output [7:0] count
);
    always @(posedge clk) begin
        if (rst) begin
            count <= 8'h00;
        end else begin
            count <= count + 1;
        end
