reg [3:0] counter;
reg [3:0] state;

always @ (posedge clk) begin
  case (state)
    4'h0: begin
      if (w == 1) state <= 4'h1;
      else state <= 4'h0;
    end
    4'h1: begin
      if (w == 1) state <= 4'h1;
      else state <= 4'h2;
    end
    4'h2: begin
      if (E == 1) state <= 4'h3;
      else state <= 4'h2;
    end
    4'h3: begin
      if (L == 1) state <= 4'h4;
      else state <= 4'h3;
    end
    4'h4: begin
      if (R == 1) state <= 4'h5;
      else state <= 4'h4;
    end
    4'h5: begin
      if (E == 1) state <= 4'h6;
      else state <= 4'h5;
    end
    4'h6: begin
      if (L == 1) state <= 4'h7;
      else state <= 4'h6;
    end
    4'h7: begin
      if (R == 1) state <= 4'h8;
      else state <= 4'h7;
    end
    4'h8: begin
      if (E == 1) state <= 4'h9;
      else state <= 4'h8;
    end
    4'h9: begin
      if (L == 1) state <= 4'hA;
      else state <= 4'h9;
    end
    4'hA: begin
      if (R == 1) state <= 4'hB;
      else state <= 4'hA;
    end
    4'hB: begin
      if (E == 1) state <= 4'hC;
      else state <= 4'hB;
    end
    4'hC: begin
      if (L == 1) state <= 4'hD;
      else state <= 4'hC;
    end
    4'hD: begin
      if (R == 1) state <= 4'hE;
      else state <= 4'hD;
    end
    4'hE: begin
      if (E == 1) state <= 4'hF;
      else state <= 4'hE;
    end
    4'hF: begin
      if (L == 1) state <= 4'h0;
      else state <= 4'hF;
    end
  endcase
end

always @ (state) begin
