module TopModule (
  input a,
  input b,
  output out_assign,
  output reg out_alwaysblock
);
  assign out_assign = b;

  always @(*) begin
    if (a & b) begin
      out_alwaysblock = 1'b1;
    end else begin
      out_alwaysblock = 1'b0;
    end
  end
endmodule

module TopModule (
  input clk,
  input a,
  input b,
  output out_assign,
  output reg out_always_comb,
  output reg out_always_ff
);
  assign out_assign = a & b;
  always_comb begin
    out_always_comb = a | b;
  end
  always @(posedge clk) begin
    out_always_ff <= a ^ b;
  end
endmodule

module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);
  assign out_assign = (a & b) ^ (sel_b1 & sel_b2);
  always @(*) begin
    if (sel_b1 & ~sel_b2) 
      out_always = a;
    else if (~sel_b1 & sel_b2)
      out_always = b;
    else
      out_always = 1'b0;
  end
endmodule

module TopModule (
