module TopModule (
  input [15:0] scancode,
  output reg left,
  output reg down,
  output reg right,
  output reg up
);
  always @(*) begin
    left = 0;
    down = 0;
    right = 0;
    up = 0;
    case(scancode)
      16'h0100: left = 1;
      16'h0200: right = 1;
      16'h0300: down = 1;
      16'h0400: up = 1;
    endcase
  end
endmodule

