    walk_ri = 0; 
  end 
	walk_left <= walk_lef; 
	walk_right <= walk_ri; 
  always @(posedge clk or posedge areset) begin 
    if (areset) begin 
      delayPeriodIndex <= 0; 
      walk_lef <= 1'b0; 
      walk_ri <= 1'b0; 
    end 
    else begin 
      if (delayPeriodIndex == 2) begin 
        delayPeriodIndex <= 0; 
        walk_lef <= 1'b1; 
        walk_ri <= 1'b0; 
      end 
      else if (delayPeriodIndex == 3) begin 
        delayPeriodIndex <= 0; 
        walk_lef <= 1'b0; 
        walk_ri <= 1'b0; 
      end 
      else if (delayPeriodIndex == 4) begin 
        delayPeriodIndex <= 0; 
