        walk_ri <= 1'b1; 
      end 
      else if (delayPeriodIndex == 5) begin 
        delayPeriodIndex <= 0; 
        walk_lef <= 1'b1; 
        walk_ri <= 1'b0; 
      end 
      if (walk_lef == 0 && walk_ri == 0) begin 
        if (bump_left) begin 
          walk_lef <= 1; 
          walk_ri <= 0; 
          delayPeriodIndex <= 3; 
        end 
        else if (bump_right) begin 
          walk_lef <= 0; 
          walk_ri <= 1; 
          delayPeriodIndex <= 5; 
        end 
      end 
      else if (walk_ri == 0 && walk_lef == 1) begin 
        if (bump_left) begin 
          walk_lef <= 1; 
          walk_ri <= 0; 
          delayPeriodIndex <= delayPeriodIndex + 1; 
        end 
        else if (bump_right) begin 
          walk_lef <= 0; 
          walk_ri <= 1; 
          delayPeriodIndex <= delayPeriodIndex + 1; 
        end 
      end 
      else if (walk_lef == 0 && walk_ri == 1) begin 
