module edge_detect(
	input clk,
	input rst_n,
	input a,

	output reg rise,
	output reg down
);
	always @(posedge clk) begin
		if (!rst_n) begin
			// Reset the outputs to zero and the internal state accordingly.
			rise <= 1'b0;
			down <= 1'b0;
		end
		else begin
			// Detect the rising edge of 'a' and set the 'rise' output.
			if (!a && a) begin
				rise <= 1'b1;
			end
			// Detect the falling edge of 'a' and set the 'down' output.
			else if (a && !a) begin
				down <= 1'b1;
				// Optionally set rise to avoid glitch, but not required according to spec.
			end
			else begin
				rise <= 1'b0;
				down <= 1'b0;
			end
		end
	end
endmodule

