IN,CLK,RST;
output reg MATCH;
reg [1:0] state;
parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

always @(*) begin
    case (state)
        S0: MATCH = (IN == 1'b1) ? 1'b0 : 1'b0;
        S1: MATCH = (IN == 1'b1) ? 1'b1 : 1'b0;
        S2: MATCH = (IN == 1'b0) ? 1'b0 : 1'b0;
        S3: MATCH = (IN == 1'b0) ? 1'b1 : 1'b0;
        default: MATCH = 1'b0;
    endcase
end

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        state <= S0;
    end else begin
        case (state)
            S0: state <= (IN == 1'b1) ? S1 : S0;
            S1: state <= (IN == 1'b0) ? S2 : S1;
            S2: state <= (IN == 1'b1) ? S3 : S2;
            S3: state <= (IN == 1'b1) ? S3 : S2;
            default: state <= S0;
        endcase
    end
end

