module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );
     reg [2:0] current_state, next_state;
     reg sequence_detected;
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) begin
             current_state <= 3'b000;
             sequence_detected <= 1'b0;
         end
         else begin
             current_state <= next_state;
             if (current_state == 3'b000) begin
                 if (data_in == 1'b1) next_state <= 3'b001;
                 else next_state <= 3'b000;
             end
             else if (current_state == 3'b001) begin
                 if (data_in == 1'b0) next_state <= 3'b010;
                 else next_state <= 3'b001;
             end
             else if (current_state == 3'b010) begin
                 if (data_in == 1'b0) next_state <= 3'b100;
                 else next_state <= 3'b010;
             end
             else if (current_state == 3'b100) begin
                 if (data_in == 1'b1) next_state <= 3'b101;
                 else next_state <= 3'b100;
             end
             else if (current_state == 3'b101) begin
                 if (data_in == 1'b0) next_state <= 3'b110;
                 else next_state <= 3'b101;
             end
             else if (current_state == 3'b110) begin
                 if (data_in == 1'b0) next_state <= 3'b111;
                 else next_state <= 3'b110;
             end
             else if (current_state == 3'b111) begin
                 if (data_in == 1'b1) next_state <= 3'b111;
                 else next_state <= 3'b111;
                 sequence_detected <= 1'b1;
             end
         end
     end
endmodule
